export function getTooltipData(args) {
    const { data } = args;
    const xLookupPoints = data.reduce((acc, d) => {
        for (const p of d.points) {
            if (p.y === null || p.hiddenInLine) {
                continue;
            }
            acc.push({
                data: p.data,
                series: p.series,
                x: p.x,
                y0: p.y0,
                y1: p.y,
            });
        }
        return acc;
    }, []);
    return { chunks: [], xLookupPoints };
}
